import socket
import errno

def handle_client(client_socket):
    try:
        data = client_socket.recv(1024)
        if not data:
            raise Exception("No data received")
        print("Received: ", data)
    except socket.error as e:
        if e.errno != errno.ECONNRESET:
            raise
        return
    except Exception as e:
        print("Error: ", e)
    finally:
        client_socket.close()

def main():
