    this.split(" ").forEach {
        when (it) {
            "+" -> stack.push(stack.pop() + stack.pop())
            "-" -> {
                val subtrahend = stack.pop()
                stack.push(stack.pop() - subtrahend)
            }
            "*" -> stack.push(stack.pop() * stack.pop())
            "/" -> {
                val divisor = stack.pop()
                stack.push(stack.pop() / divisor)
            }
            else -> stack.push(it.toDouble())
        }
    }
