import Foundation

func sendRequest(urlString: String) {
    guard let url = URL(string: urlString.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed)!) else { 
        print("Invalid URL")
        return 
    }

    var request = URLRequest(url: url)
