type Counter struct {
	sync.Mutex
	count int
}

func (c *Counter) Increment(wg *sync.WaitGroup) {
	c.Lock()
	defer c.Unlock()
	defer wg.Done()
	for i := 0; i < 1000; i++ {
		c.count++
	}
}

func main() {
	var wg sync.WaitGroup
	counter := Counter{}
	for i := 0; i < 20; i++ {
