void copyString(char* destination, const char* source, size_t destSize) {
    size_t len = strlen(source);
    if(len < destSize) {
        memcpy(destination, source, len + 1);
    } else {
        memcpy(destination, source, destSize - 1);
        destination[destSize - 1] = '\0';
    }
}

